"""Package the existing Assist Tasks runtime, styles and assets used by the guided homepage paths."""
from pathlib import Path
import re
import shutil

dest = Path(__file__).resolve().parent
site = dest.parents[3] / "08 - Generated Screens/AI Assist/task-first-assist/site"
shell = (site / "assist/index.html").read_text()
# Keep the shared date picker styles. The standalone review controller and dock are unused.
shell = re.sub(r'<script [^>]*(?:ui-directions|navbar-motion)[^>]*></script>|<link [^>]*navbar-motion[^>]*>', '', shell)

def stylesheet(match):
    return '<style>\n' + (site / match[1]).read_text() + '\n</style>'

def script(match):
    name = match[1]
    source = (site / name).read_text()
    if name == 'sitter-v3.js':
        # Use the upstream saved-sitter fixture without running its standalone route controller.
        source = source.replace("location.pathname.split('/').filter(Boolean)[0] || ''", "'sitter-v3'", 1)
    if name == 'assets/thinking-orb.js':
        return '<script src="../../thinking-orb.js"></script>'
    return '<script>\n' + source + '\n</script>'

shell = re.sub(r'<link rel="stylesheet" href="/([^"?]+)(?:\?[^"]*)?">', stylesheet, shell)
shell = re.sub(r'<script src="/([^"?]+)(?:\?[^"]*)?"></script>', script, shell)
shell = shell.replace('/assets/', './art/')
shell = shell.replace('${A}illus/', '../../assets/illus/').replace("A + 'illus/", "'../../assets/illus/")
# The guide controls scroll placement inside the chat while the outer page owns native scroll.
shell = shell.replace('</head>', '<style>.sheet{transition:none}.chat{scroll-behavior:auto}#toast{display:none}</style></head>')
(dest / 'runtime.html').write_text('<!-- Generated by export.py from the shared Assist Tasks prototype. -->\n'+shell)
assets = """aisha.webp app-icon-180.png assist-clover-knit.png assist-clover.webp
clay/calendar-check.png clay/event.png clay/two-people.png dana.webp db-rest.webp elena.webp
jake.webp kid-cutout.webp maya.webp orb.webp priya.webp sitters/man.webp sitters/woman.webp ssc-logo.webp tony.webp""".split()
for name in assets:
    target = dest / 'art' / name
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(site / 'assets' / name, target)
